  --warn:      #FFB53D;
  --bad:       #FF4133;
  --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Consolas, monospace;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
20→html, body {
  background: var(--bg); color: var(--text);
  margin: 0; padding: 0;
