header.topbar {
  display: flex;
  border-bottom: 1px solid var(--border);
50→  background: linear-gradient(180deg, var(--panel) 0%, var(--bg) 100%);
  position: sticky; top: 0; z-index: 10;
  -webkit-backdrop-filter: saturate(180%) blur(8px);
  backdrop-filter: saturate(180%) blur(8px);
}
.topbar-inner {
  display: flex; align-items: center; gap: 16px;
  width: 100%; max-width: 1400px; margin: 0 auto;
  padding: 10px 20px;
}
60→.topbar .brand {
  font-weight: 600; letter-spacing: -0.01em; font-size: 14px;
  display: flex; align-items: center; gap: 8px;
}
.topbar .brand::before {
  content: ""; display: inline-block; width: 8px; height: 8px;
  background: var(--accent); border-radius: 2px;
  box-shadow: 0 0 12px var(--accent);
}
.topbar nav { display: flex; flex-wrap: wrap; gap: 2px; margin-left: 12px; }
70→.topbar nav a {
  padding: 5px 10px; border-radius: 6px;
  color: var(--muted); font-size: 13px; font-weight: 500;
  text-transform: capitalize;
  transition: color 120ms, background 120ms;
}
.topbar nav a:hover { color: var(--text); background: var(--panel-2); text-decoration: none; }
.topbar nav a.active { color: var(--text); background: var(--panel-2); }

.topbar .spacer { margin-left: auto; }
80→.topbar .pill {
  padding: 4px 10px; border-radius: 6px;
  background: var(--panel-2); border: 1px solid var(--border);
  color: var(--muted); font-size: 12px; font-family: var(--mono);
}

/* main */
main#app { padding: 24px 20px; max-width: 1400px; margin: 0 auto; }

/* card */
90→.card {
  position: relative;
  background: linear-gradient(160deg, var(--panel) 0%, var(--panel-2) 100%);
  border: 1px solid var(--border);
  border-left: 2.5px solid var(--accent);
  border-radius: 10px;
  padding: 18px;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  box-shadow: 0 0 0 1px rgba(39, 224, 255, 0.06), 0 8px 24px -12px rgba(39, 224, 255, 0.2);
100→}
.card h2 { margin: 0 0 14px; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.card h3 { margin: 0 0 10px; font-size: 13px; font-weight: 600; color: var(--text); }

