/* ══════════════════════════════════════════════════════════════════════════
   JARVIS / IRONMAN HUD LAYOUT (ported from jarvis_ui feat/ironman-hud-ui)
   Source: HudBackground.tsx, HudCorners.tsx, HudPanel.tsx + globals.css
   Applied when <html class="hud-theme"> (or body). See hud-background.js.
   ══════════════════════════════════════════════════════════════════════════ */

.hud-theme {
  color-scheme: dark;

  /* HUD accent ramp */
  --hud-cyan:      #27e0ff;
  --hud-cyan-soft: rgba(39, 224, 255, 0.5);
  --hud-cyan-dim:  rgba(39, 224, 255, 0.12);
  --hud-gold:      #ffb53d;
  --hud-gold-soft: rgba(255, 181, 61, 0.5);
  --hud-red:       #ff4133;
  --font-hud:      ui-monospace, 'JetBrains Mono', 'SF Mono', system-ui, sans-serif;

  /* Deep void surfaces (override base tokens) */
  --bg:           #050410;
  --panel:        rgba(8, 12, 26, 0.82);
  --panel-2:      rgba(7, 10, 20, 0.92);
  --border:       rgba(120, 200, 255, 0.18);
  --border-2:     rgba(120, 220, 255, 0.28);
  --text:         rgba(226, 244, 255, 0.92);
  --muted:        rgba(196, 226, 255, 0.62);
  --muted-2:      rgba(170, 210, 255, 0.44);
  --accent:       #27e0ff;
  --accent-2:     #ffb53d;

  /* Ink hierarchy */
  --ink:   rgba(226, 244, 255, 0.92);
  --ink-2: rgba(196, 226, 255, 0.62);
  --ink-3: rgba(170, 210, 255, 0.44);
  --ink-4: rgba(150, 195, 255, 0.26);

  /* Separators / fills */
  --separator:        rgba(120, 220, 255, 0.14);
  --separator-strong: rgba(120, 220, 255, 0.24);
  --fill:   rgba(40, 130, 190, 0.08);
  --fill-2: rgba(40, 130, 190, 0.14);

  /* Status */
  --good:   #30d9b8;
  --warn:   #ffb53d;
  --bad:    #ff4133;

  /* Chart tokens tuned for void */
  --chart-tick:     rgba(180, 220, 255, 0.5);
  --chart-grid:     rgba(39, 224, 255, 0.13);
  --chart-contrast: #050410;

  /* Glass / panel glow language (cyan primary) */
  --glass-tint:        rgba(8, 18, 34, 0.5);
  --glass-tint-soft:   rgba(10, 22, 40, 0.4);
  --glass-edge:        rgba(130, 235, 255, 0.55);
  --glass-edge-dim:    rgba(255, 181, 61, 0.18);

  /* Shadows used by cards/panels */
  --shadow-card:
    0 0 0 0.5px rgba(120, 220, 255, 0.10),
    0 40px 100px rgba(0, 0, 0, 0.85),
    0 0 60px rgba(39, 224, 255, 0.10),
    inset 0 1px 0 rgba(130, 235, 255, 0.2);
}

/* Background + scanlines utilities (apply to main containers or html) */
.hud-void-bg {
  background:
    radial-gradient(circle at 50% 52%, rgba(39, 150, 224, 0.13), transparent 40%),
    radial-gradient(circle at 50% 92%, rgba(255, 160, 50, 0.06), transparent 30%),
    linear-gradient(180deg, #050610 0%, #0a0817 48%, #04030a 100%);
}

.hud-scanlines {
  position: relative;
}
.hud-scanlines::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  background:
    linear-gradient(rgba(150, 220, 255, 0.025) 50%, rgba(0, 0, 0, 0.07) 50%),
    radial-gradient(circle at 50% 48%, transparent 0 54%, rgba(0, 0, 0, 0.4) 94%);
  background-size: 100% 4px, 100% 100%;
  mix-blend-mode: screen;
  opacity: 0.5;
}

/* Signature HUD panel (glass + left accent rail + corner glow) */
.hud-panel {
  --hud-accent: var(--hud-cyan);
  --hud-accent-soft: var(--hud-cyan-soft);
  position: relative;
  border: 1px solid rgba(120, 200, 255, 0.2);
  border-left: 2.5px solid var(--hud-accent-soft);
  background: linear-gradient(180deg, rgba(4, 10, 22, 0.9), rgba(6, 8, 20, 0.78));
  backdrop-filter: saturate(150%) blur(14px);
  -webkit-backdrop-filter: saturate(150%) blur(14px);
  box-shadow:
    0 0 0 1px rgba(39, 224, 255, 0.05),
    0 0 26px color-mix(in srgb, var(--hud-accent) 18%, transparent),
    inset 0 0 24px color-mix(in srgb, var(--hud-accent) 5%, transparent);
  border-radius: 10px;
}
.hud-panel-gold {
  --hud-accent: var(--hud-gold);
  --hud-accent-soft: var(--hud-gold-soft);
}
.hud-panel:hover {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--hud-accent) 14%, transparent),
    0 0 40px color-mix(in srgb, var(--hud-accent) 30%, transparent),
    inset 0 0 30px color-mix(in srgb, var(--hud-accent) 8%, transparent);
}

/* Font treatment for titles / brand (geometric HUD feel; no external font) */
.font-hud {
  font-family: var(--font-hud);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* HUD corner brackets (used via JS helper or manually) */
.hud-corner { border-color: rgba(39,224,255,0.55); }

/* Keyframes (sweep on top rail of panels, flicker on titles, optional scan) */
@keyframes hud-sweep {
  0%        { transform: translateX(-100%); opacity: 0; }
  18%, 82%  { opacity: 1; }
  100%      { transform: translateX(100%);  opacity: 0; }
}
@keyframes hud-flicker {
  0%, 100%  { opacity: 1; }
  47%       { opacity: 1; }
  48%       { opacity: 0.55; }
  49%       { opacity: 1; }
  72%       { opacity: 0.78; }
  73%       { opacity: 1; }
}
@keyframes hud-scan-down {
  0%   { transform: translateY(-100%); opacity: 0; }
  8%   { opacity: 0.7; }
  92%  { opacity: 0.7; }
  100% { transform: translateY(100%); opacity: 0; }
}

.animate-hud-sweep {
  animation: hud-sweep 4s ease-in-out infinite;
}
.animate-hud-flicker {
  animation: hud-flicker 3.5s ease-in-out infinite;
}

