rawInput.command:
# Find usage/token fields in grok chat history
python3 << 'PY'
import json, os
from pathlib import Path
root = Path.home()/".grok"/"sessions"
samples = []
for p in root.rglob("chat_history.jsonl"):
    try:
        with open(p) as f:
            for i, line in enumerate(f):
                if i>50: break
                o=json.loads(line)
                samples.append((str(p), o))
                if i>=2: break
    except Exception as e:
        pass
    if len(samples)>=6: break

# Collect all keys and any usage-like fields
usage_keys = set()
all_keys = set()
models = set()
roles = set()
types = set()
for path,o in samples:
    all_keys |= set(o.keys())
    for k in o:
        if 'token' in k.lower() or 'usage' in k.lower() or 'cost' in k.lower() or 'model' in k.lower():
            usage_keys.add(k)
    # dig one level
    for k,v in o.items():
        if isinstance(v, dict):
            for kk in v:
                if any(x in kk.lower() for x in ('token','usage','cost','model')):
                    usage_keys.add(f"{k}.{kk}")
            if 'model' in v: models.add(str(v.get('model')))
        if k=='role': roles.add(v)
        if k=='type': types.add(v)
        if k=='model': models.add(str(v))

print("sample paths:", len(samples))
print("top keys union:", sorted(all_keys))
print("usage-like:", sorted(usage_keys))
print("roles:", roles)
print("types:", types)
print("models:", models)

# Find a line with usage
found=0
for p in root.rglob("chat_history.jsonl"):
    with open(p) as f:
        for line in f:
            if 'usage' in line or 'token' in line.lower() or 'prompt_tokens' in line or 'completion' in line:
                o=json.loads(line)
                print("HIT", p)
                print(json.dumps(o, indent=2)[:3000])
                found+=1
                break
    if found>=2: break
if not found:
    print("NO usage/token fields found in chat_history samples")
    # try events
    for p in root.rglob("events.jsonl"):
        with open(p) as f:
            for i,line in enumerate(f):
                if i>100: break
                if 'usage' in line or 'token' in line.lower():
                    o=json.loads(line)
                    print("EVENT HIT", p)
                    print(json.dumps(o, indent=2)[:2500])
                    found+=1
                    break
        if found>=2: break
    if not found:
        print("NO usage in events either - show event types")
        from collections import Counter
        c=Counter()
        for p in list(root.rglob("events.jsonl"))[:5]:
            with open(p) as f:
                for line in f:
                    try:
                        o=json.loads(line)
                        c[o.get('type') or o.get('event') or o.get('kind') or list(o.keys())[:3].__repr__()]+=1
                    except: pass
        print(c.most_common(30))
PY

